/* Read mode: quiet paper, a stable reading column, and explicit comparisons. */
:root {
  --ink: #263e52;
  --muted: #526a7e;
  --accent: #173f63;
  --line: #d5e0e8;
  --paper: #ffffff;
  --wash: #edf2f6;
  --warm: #fff5e3;
  --warning: #6d491a;
  --rail: 216px;
}
* { box-sizing: border-box; }
html { scroll-padding-top: 80px; }
body {
  margin: 0;
  background: var(--paper);
  color: var(--ink);
  font: 17px/1.8 "Study Sans", "Microsoft JhengHei", sans-serif;
  -webkit-font-smoothing: antialiased;
}
::selection { background: #d6e7da; color: #142b21; }
.en { display: none; }
body[data-lang=en] .en, body[data-lang=both] .en { display: block; }
body[data-lang=en] .tc { display: none; }
body[data-lang=en] { line-height: 1.7; }
body[data-lang=both] .en:not(:first-child) {
  margin-top: .65em;
  color: var(--muted);
}
a { color: var(--accent); text-underline-offset: 3px; text-decoration-thickness: 1px; }
a:hover { text-decoration-thickness: 2px; }
button { font: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
}
.skip-link { position: fixed; left: 16px; top: -100px; z-index: 10; padding: 10px 16px; background: white; }
.skip-link:focus { top: 8px; }
.toolbar { position: sticky; top: 0; z-index: 5; background: white; border-bottom: 1px solid var(--line); }
.toolbar-inner { max-width: 1440px; margin: auto; padding: 10px 32px; display: flex; align-items: center; gap: 16px; }
.brand { margin-right: auto; font-size: 13px; font-weight: 650; line-height: 1.4; }
.languages { display: flex; gap: 3px; flex-shrink: 0; }
.languages button { color: var(--muted); background: white; border: 1px solid transparent; border-radius: 3px; padding: 4px 9px; font-size: 12px; line-height: 1.5; min-height: 28px; }
.languages button:hover { background: var(--wash); }
.languages button[aria-pressed=true] { color: white; background: var(--accent); }
.layout { display: grid; grid-template-columns: var(--rail) minmax(0, 1fr); gap: 48px; max-width: 1440px; margin: auto; padding: 44px 32px 80px; }
.sidebar { position: sticky; top: 90px; align-self: start; max-height: calc(100vh - 112px); overflow: auto; padding-right: 14px; scrollbar-width: thin; scrollbar-color: #c4cec5 transparent; }
.sidebar h2 { font-size: 13px; font-weight: 600; color: var(--muted); margin: 0 0 18px; }
.sidebar a { display: grid; grid-template-columns: 22px minmax(0, 1fr); column-gap: 8px; padding: 9px 8px; margin: 0 0 3px; color: var(--muted); text-decoration: none; font-size: 13px; line-height: 1.55; border-radius: 3px; }
.nav-number { font-variant-numeric: tabular-nums; color: #637367; }
.sidebar a:hover, .sidebar a[aria-current=location] { color: var(--accent); background: var(--wash); }
.sidebar a[aria-current=location] { font-weight: 650; }
.sidebar a[aria-current=location] .nav-number { color: var(--accent); }
main { min-width: 0; max-width: 1060px; }
.hero { padding: 0 0 32px; margin-bottom: 32px; border-bottom: 1px solid var(--line); }
.hero h1 { font-size: 34px; line-height: 1.4; letter-spacing: -.025em; font-weight: 650; max-width: 32em; margin: 0; text-wrap: pretty; }
.chapter { margin: 0 0 64px; }
.chapter + .chapter { border-top: 1px solid var(--line); padding-top: 36px; }
.section-heading { display: flex; align-items: baseline; gap: 14px; margin: 0 0 14px; }
.section-number { font-size: 14px; font-weight: 500; font-variant-numeric: tabular-nums; color: var(--accent); min-width: 24px; }
h2 { font-size: 25px; line-height: 1.45; font-weight: 650; letter-spacing: -.02em; margin: 0; text-wrap: pretty; }
h3 { font-size: 17px; line-height: 1.6; font-weight: 650; margin: 0 0 16px; }
.intro { max-width: 72ch; margin: 0 0 30px 38px; color: var(--muted); }
.table-wrap { margin: 32px 0; }
table { width: 100%; table-layout: fixed; border-collapse: collapse; }
th, td { text-align: left; vertical-align: top; overflow-wrap: anywhere; }
thead th { padding: 12px 16px; color: var(--muted); font-size: 13px; font-weight: 500; border-top: 1px solid var(--ink); border-bottom: 1px solid var(--line); }
thead th:first-child { width: 19%; padding-left: 0; }
thead th:nth-child(2) { width: 49%; }
thead th:nth-child(3) { width: 32%; }
tbody th { color: var(--accent); font-size: 16px; line-height: 1.65; font-weight: 650; padding: 24px 16px 14px 0; }
tbody tr:first-child td { padding: 24px 16px 18px; font-size: 16px; }
tbody tr:first-child td:last-child { background: var(--warm); }
tbody + tbody { border-top: 1px solid var(--line); }
.citation-row td { padding: 0 0 22px; }
.citations { font-size: 12px; line-height: 1.65; color: var(--muted); }
.source-citation { margin-top: 10px; overflow-wrap: anywhere; }
.source-citation a { color: var(--muted); text-decoration-color: #a6b7a9; }
.locator { display: block; }
.flow { margin: 30px 0 36px; padding: 24px; background: var(--wash); }
.flow h3 { margin-bottom: 20px; }
.flow-node { position: relative; padding: 18px 20px; background: white; border: 1px solid #d0dbd1; border-radius: 3px; font-size: 16px; line-height: 1.75; }
.flow-node > .tc, .flow-node > .en { max-width: 72ch; }
.step { font-size: 12px; line-height: 1.5; font-weight: 600; color: var(--accent); margin-bottom: 8px; font-variant-numeric: tabular-nums; }
.arrow { position: relative; height: 28px; width: 100%; font-size: 0; }
.arrow::before { content: ''; position: absolute; left: 50%; top: 0; height: 23px; border-left: 1px solid #82998a; }
.arrow::after { content: ''; position: absolute; left: calc(50% - 3px); top: 18px; width: 7px; height: 7px; border-right: 1px solid #82998a; border-bottom: 1px solid #82998a; transform: rotate(45deg); }
.branches { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.outcome { background: #e9f2e8; border-color: #a6bea9; }
.action { background: #fff7e5; border-color: #d8c59e; }
.stop { background: #273c32; border-color: #273c32; color: white; }
body[data-lang=both] .stop .en { color: #e1e9df; }
.legend { font-size: 12px; color: var(--muted); margin: 16px 0; }
.flow-stack > .flow-node + .flow-node { margin-top: 12px; }
.third-flow > .arrow { width: 50%; margin-left: 50%; }
.third-flow > .flow-node { margin-left: calc(50% + 8px); }
.note, .example { margin: 30px 0; padding: 20px 0; border-top: 1px solid var(--line); border-bottom: 1px solid var(--line); }
.note h3, .example h3 { color: var(--accent); margin-bottom: 8px; }
.note p, .example p { margin: 0; max-width: 72ch; font-size: 16px; }
.example { padding: 20px 24px; border: 0; background: var(--warm); }
.question-map { font-size: 12px; line-height: 1.9; color: var(--muted); margin-top: 24px; }
.question-map > .tc, .question-map > .en { margin-bottom: 4px; }
.qid { display: inline-block; font-size: 12px; margin: 0 10px 0 0; font-variant-numeric: tabular-nums; }
footer { font-size: 13px; line-height: 1.8; color: var(--muted); border-top: 1px solid var(--line); padding-top: 24px; }
[hidden] { display: none !important; }
@media (min-width: 1500px) { .layout { gap: 64px; } }
@media (max-width: 1050px) {
  :root { --rail: 184px; }
  .layout { padding-left: 24px; padding-right: 24px; gap: 30px; }
  .sidebar a { font-size: 12px; }
  thead th:first-child { width: 21%; }
  thead th:nth-child(2) { width: 47%; }
  tbody tr:first-child td { padding-left: 12px; padding-right: 12px; }
}
@media (max-width: 800px) {
  .toolbar-inner { padding-left: 20px; padding-right: 20px; }
  .layout { display: block; padding: 24px 20px 48px; }
  .sidebar { position: static; max-height: none; padding: 0 0 22px; margin-bottom: 28px; border-bottom: 1px solid var(--line); }
  .sidebar h2 { margin-bottom: 10px; }
  .sidebar nav { display: flex; gap: 8px; overflow: auto; padding: 6px 6px 10px; }
  .sidebar a { flex: 0 0 195px; padding: 10px; background: var(--wash); margin: 0; font-size: 13px; }
  .hero h1 { font-size: 28px; }
  .intro { margin-left: 0; }
}
@media (max-width: 600px) {
  body { font-size: 16px; }
  html { scroll-padding-top: 120px; }
  .toolbar-inner { padding: 10px 16px; gap: 8px; flex-wrap: wrap; }
  .brand { font-size: 12px; flex-basis: 100%; }
  .languages button { font-size: 12px; padding: 4px 9px; }
  .layout { padding: 24px 16px 40px; }
  .hero { margin-bottom: 28px; padding-bottom: 28px; }
  .hero h1 { font-size: 26px; line-height: 1.45; }
  .section-heading { gap: 8px; }
  .section-number { min-width: 22px; }
  h2 { font-size: 22px; }
  .chapter { margin-bottom: 44px; }
  .chapter + .chapter { padding-top: 28px; }
  .flow { margin-left: -2px; margin-right: -2px; padding: 16px; }
  .flow-node { padding: 16px; }
  .branches { grid-template-columns: 1fr; gap: 16px; }
  .third-flow > .flow-node, .third-flow > .arrow { margin-left: 0; width: 100%; }
  table, tbody, tr, td, tbody th { display: block; width: 100%; }
  thead { display: none; }
  .table-wrap { margin: 30px 0; }
  tbody:first-of-type th { border-top: 1px solid var(--ink); }
  tbody th { padding: 20px 0 12px; font-size: 17px; }
  tbody tr:first-child td { padding: 0 0 16px; font-size: 16px; }
  tbody tr:first-child td:last-child { padding: 16px; margin-bottom: 16px; }
  tbody tr:first-child td::before { display: block; font-size: 12px; font-weight: 600; color: var(--muted); margin-bottom: 8px; }
  tbody tr:first-child td:nth-child(2)::before { content: '規則 / Rule'; }
  tbody tr:first-child td:nth-child(3)::before { content: '容易混淆 / Easy to confuse'; color: var(--warning); }
  body[data-lang=tc] tbody tr:first-child td:nth-child(2)::before { content: '規則'; }
  body[data-lang=tc] tbody tr:first-child td:nth-child(3)::before { content: '容易混淆'; }
  body[data-lang=en] tbody tr:first-child td:nth-child(2)::before { content: 'Rule'; }
  body[data-lang=en] tbody tr:first-child td:nth-child(3)::before { content: 'Easy to confuse'; }
  .citation-row td { padding: 0 0 24px; }
  .note, .example { margin: 24px 0; }
  .example { padding: 16px; }
}
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; } }
@media print {
  .toolbar, .sidebar, .skip-link, .question-map { display: none !important; }
  .layout { display: block; padding: 0; }
  body { font-size: 11pt; }
  main { max-width: none; }
  .hero h1 { font-size: 22pt; }
  .chapter { margin-bottom: 30px; }
  h2, h3 { break-after: avoid; }
  .flow, .note, .example, tbody { break-inside: avoid; }
  .citations { font-size: 9pt; }
}

