/* Source-first reading: requirements remain beside their conditions. */
.part-intro{max-width:72ch;color:var(--muted);margin:0 0 36px}
.concept-block{margin:26px 0 32px;max-width:78ch}
.concept-block h3{font-size:17px;margin:0 0 14px}
.concept-list{margin:0;padding-left:1.25em}
.concept-list li{padding-left:.35em;margin:0 0 18px;line-height:1.9}
.concept-list li::marker{color:#8297aa;font-size:.8em}
.concept-block>.citations{margin-top:20px;padding-left:1.6em;border-top:1px solid var(--line);padding-top:6px}
.concept-block.flow>.citations{padding-left:0}
@media(max-width:600px){.concept-list li{line-height:1.85;margin-bottom:18px}.concept-block{margin-top:22px}.concept-block>.citations{padding-left:0}.section-heading{align-items:flex-start}.section-number{padding-top:5px}}

/* Recall aids use the same B paper and rules, with conditions attached to rows. */
.recall-term{font-weight:650;color:var(--ink)}
.memory-panel{margin:28px 0 40px;max-width:100%;min-width:0}
.memory-panel>h3{font-size:22px;line-height:1.5;margin:0 0 20px}
.memory-table{font-size:16px;line-height:1.8}
.memory-table thead th{padding:12px 16px;font-size:13px;font-weight:600}
.memory-table thead th:first-child{width:23%;padding-left:0}
.memory-table thead th:nth-child(2){width:35%}
.memory-table thead th:nth-child(3){width:42%}
.memory-table tbody th{padding:20px 16px 20px 0;font-size:16px;line-height:1.8}
.memory-table tbody tr:first-child td{padding:20px 16px;font-size:16px;line-height:1.8}
.memory-table tbody tr:first-child td:last-child{background:transparent;padding-right:0}
.memory-value{font-weight:600}
.cell-label{display:none}
.memory-note{font-size:16px;line-height:1.8;padding-top:16px;margin:4px 0 20px;border-top:1px solid var(--line)}
.memory-panel>.citations{padding-top:12px;border-top:1px solid var(--line)}
.stage-sequence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px;list-style:none;padding:24px 0;margin:0 0 20px;border-top:1px solid var(--ink);border-bottom:1px solid var(--line)}
.stage-sequence li{position:relative;min-width:0}
.stage-sequence li+li{border-left:1px solid var(--line);padding-left:24px}
.stage-sequence li:not(:last-child)::after{content:none}
.stage-sequence h4{font-size:22px;line-height:1.5;font-weight:650;color:var(--accent);margin:0 0 12px;overflow-wrap:anywhere}
