/* Relationship words, local branches and independent clock origins carry meaning.
   No remote assets, pan/zoom requirement or colour-only semantic distinction. */
.visual-intro{font-size:16px;line-height:1.8;margin:0 0 24px;max-width:76ch}
.memory-panel h4{font-size:17px;line-height:1.6;margin:0 0 14px;color:var(--accent)}
.visual-paths{border-top:1px solid var(--line)}
.visual-path{padding:24px 0;border-bottom:1px solid var(--line)}
.path-track{display:flex;align-items:center;gap:12px}
.path-node{flex:1;min-width:0;padding:12px 0;border-top:2px solid var(--accent);font-size:16px;font-weight:600;overflow-wrap:anywhere}
